        app.activate()

        // Wait for app to be ready
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")

        // Try to dismiss any alerts
        let alerts = XCUIApplication.alerts
        if alerts.count > 0 {
            let openButton = XCUIApplication.buttons.matching(NSPredicate(format: "label == 'Open'")).firstMatch
            if openButton.exists {
                openButton.tap()
            }
        }

        // Wait and take screenshots
        sleep(2)

        // Now navigate to search
        let searchButton = app.buttons.matching(NSPredicate(format: "identifier CONTAINS 'search' || label CONTAINS 'Search'")).firstMatch
        if searchButton.exists {
            searchButton.tap()
            sleep(1)
        }

        // Search for "test"
        let searchField = app.searchFields.firstMatch
        if searchField.exists {
            searchField.tap()
            searchField.typeText("test")
            sleep(1)
        }

        // Tap on the People tab
        let peopleTab = app.buttons.matching(NSPredicate(format: "label == 'People'")).firstMatch
        if peopleTab.exists {
            peopleTab.tap()
            sleep(1)
        }
    }
}
